			AssertEquals("JWT Header should be empty", string.Empty, headerJson);
			AssertEquals("JWT Payload should be empty", string.Empty, payloadJson);
			AssertEquals("JWT Signature should be empty", System.Array.Empty<byte>(), signature);

			bizo.AHF_AuthorisationData = ZBlob.FromAscii("eyJhbGciOiJodHRwOi8vd3d3LnczLm9yZy8yMDAxLzA0L3htbGRzaWctbW9yZSNyc2Etc2hhMjU2Iiwia2lkIjoiMTE1RjQ0MjY2MTdBNzkzOEJFMUJBMDZEQkVFOTFBNDI3NTg0RURBQiIsInR5cCI6IkpXVCIsIng1dCI6IkVWOUVKbUY2ZVRpLUc2QnR2dWthUW5XRTdhcyJ9..gneVG9r-muKkwkhH-FXbXSIAR5oYE81fGQ641Ny9-iYMz8M4kTn8Y3Kk52yz-ONXiHE5NW90VH-baa-Z1OWuG2qk5wILIRAKRrtxuBT2dr77cMmnzYto0V10ClQ8EvUW7hMVrLDnhh-0vjiPR4cecc1nq2AbNW5AFPdwAw4d9NoOXbvqrpvjXiD7gFP7DExuA6Lteuu14p5DArPAw7wa0YEjZBn7xMtbDtgwze3wZKbohnlj-HYEvpHjqDdBOKdDKR4Ujx2E-eHNr1y2TANm3Todv8NL2u6lCX2T-JvwmyAN3H-59FHed-x7bttEel8biF_O1H_-FPLiVMYnbH6Pxw");
