		public void TestQRCodeJwtParts()
		{
			var bizo = (IndiaAccTransactionHeaderAuthorisationRecord)GetNewBusinessObject();
			var (headerJson, payloadJson, signature) = bizo.GetQRCodeJwtParts();
			AssertEquals("JWT Header should be empty", string.Empty, headerJson);
			AssertEquals("JWT Payload should be empty", string.Empty, payloadJson);
			AssertEquals("JWT Signature should be empty", System.Array.Empty<byte>(), signature);

			bizo.AHF_VerificationUrl = "eyJhbGciOiJodHRwOi8vd3d3LnczLm9yZy8yMDAxLzA0L3htbGRzaWctbW9yZSNyc2Etc2hhMjU2Iiwia2lkIjoiMTE1RjQ0MjY2MTdBNzkzOEJFMUJBMDZEQkVFOTFBNDI3NTg0RURBQiIsInR5cCI6IkpXVCIsIng1dCI6IkVWOUVKbUY2ZVRpLUc2QnR2dWthUW5XRTdhcyJ9..M4Qp-_WzHkEY76HY5X4IU1faDyb2Jikpjxog1DGIKhbk5rceLWEZWurUp7IYkyXo07TbsmNEaSEqA3IBtv5Wn2h79qkQ3lDjgdLyFbyWJAoj4j7AfUKw65WOhCW86qncDy70lby1xuzFnp1MRc0h-bJxPyU2amVo72HGqEP4tk5a0rfaqXQMUE_C32oY2Nl68mlQMlKbERMZfgtQfraUz1gwP81qOcdUMGHabk8RwG-hfxvWL6kENAD29PBniKyKQziyN2Em82do5_wCLYNZzZnzclgngR6mjOeOFkH5t46bIbozkVdYJ1sNvDor9RpbAZEC_F3HltVUmtitJ37lOw";
			(headerJson, payloadJson, signature) = bizo.GetQRCodeJwtParts();
			AssertEquals("JWT Header should be parsed from VerificationUrl", "{'alg':'http://www.w3.org/2001/04/xmldsig-more#rsa-sha256','kid':'115F4426617A7938BE1BA06DBEE91A427584EDAB','typ':'JWT','x5t':'EV9EJmF6eTi-G6BtvukaQnWE7as'}".Replace("'", "\""), headerJson);
			AssertEquals("JWT Payload should be parsed from VerificationUrl", "{'data':'{\\'SellerGstin\\':\\'06AAACE2126J1Z0\\',\\'BuyerGstin\\':\\'28AAACG0569P1Z3\\',\\'DocNo\\':\\'55\\',\\'DocTyp\\':\\'INV\\',\\'DocDt\\':\\'2020-02-26\\',\\'TotInvVal\\':12400,\\'ItemCnt\\':1,\\'MainHsnCode\\':\\'1001\\',\\'Irn\\':\\'3d125a78429c62bd7af3a2bc7474ce0f4929ffdb6754e33ca874e52ef352b2e8\\'}','iss':'NIC'}".Replace("'", "\""), payloadJson);
